omonimi as (
  select lower(s.nome_scientifico) k, count(*) n from specie s
  join v on lower(s.nome_scientifico) = lower(v.sci) group by 1
),
calcolati as (
  select s.id, (select string_agg(x, ' | ') from unnest(string_to_array(v.alt, ' | ')) x
                where lower(x) <> lower(s.nome)) as alt
  from specie s
  join v on lower(s.nome_scientifico) = lower(v.sci)
  join omonimi o on o.k = lower(s.nome_scientifico) and o.n = 1
  where s.specie_padre_id is null and s.nomi_alternativi is null
    and s.slug <> all (array['abies-recurvata', 'acalypha-wilkesiana', 'acanthus-hungaricus', 'acer-x-freemanii', 'acis-autumnalis', 'actinidia-polygama', 'adromischus-cooperi', 'adromischus-cristatus', 'agave-salmiana', 'aglaonema-modestum', 'alocasia-micholitziana', 'aloe-humilis', 'aloe-perfoliata', 'aloe-rauhii', 'aloiampelos-striatula', 'ambrosia-trifida', 'amsinckia-lycopsoides', 'anemone-blanda', 'anthurium-crystallinum', 'aphelandra-squarrosa', 'archontophoenix-alexandrae', 'artemisia-cina', 'artemisia-ludoviciana', 'artemisia-schmidtiana', 'asparagus-asparagoides', 'astrophytum-capricorne', 'astrophytum-ornatum', 'begonia-maculata', 'begonia-rex', 'betonica-hirsuta', 'bombax-ceiba', 'brachychiton-acerifolius', 'brunfelsia-pauciflora', 'bursera-simaruba', 'callirhoe-involucrata', 'callisia-repens', 'campanula-rotundifolia', 'carpesium-abrotanoides', 'cercis-griffithii', 'cereus-hildmannianus', 'cereus-repandus', 'clematis-virginiana', 'cleome-houtteana', 'cobaea-scandens', 'coleus-caninus', 'cotoneaster-x-suecicus', 'crataegus-orientalis', 'crinum-bulbispermum', 'crinum-moorei', 'crocus-x-luteus', 'ctenanthe-lubbersiana', 'cyrtanthus-elatus', 'dactylorhiza-elata', 'daphne-tangutica', 'dasylirion-serratifolium', 'davallia-canariensis', 'delosperma-echinatum', 'dendrobium-anosmum', 'desmodium-triflorum', 'diascia-rigescens', 'dietes-bicolor', 'dietes-grandiflora', 'digitalis-minor', 'dioscorea-alata', 'dodonaea-viscosa', 'dracaena-surculosa', 'dryopteris-oreades', 'dudleya-edulis', 'durio-zibethinus', 'echeveria-colorata', 'echeveria-elegans', 'echeveria-secunda', 'elsholtzia-ciliata', 'embothrium-coccineum', 'encephalartos-villosus', 'eschscholzia-caespitosa', 'eucharis-amazonica', 'euphorbia-meloformis', 'euphorbia-tithymaloides', 'exochorda-racemosa', 'faucaria-tigrina', 'ferocactus-glaucescens', 'festuca-gautieri', 'ficus-cyathistipula', 'fragaria-chiloensis', 'gasteria-carinata', 'geranium-phaeum', 'geranium-renardii', 'glandora-prostrata', 'goeppertia-ke